use ai_platform_client::{Client,Error};use serde_json::json;use tokio::{io::{AsyncReadExt,AsyncWriteExt},net::TcpListener};
async fn server(status:u16,body:&str)->(String,tokio::task::JoinHandle<String>){let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let body=body.to_owned();let task=tokio::spawn(async move{let(mut socket,_)=listener.accept().await.unwrap();let mut bytes=Vec::new();loop{let mut chunk=[0u8;4096];let n=socket.read(&mut chunk).await.unwrap();if n==0{break}bytes.extend_from_slice(&chunk[..n]);if let Some(end)=bytes.windows(4).position(|s|s==b"\r\n\r\n"){let headers=String::from_utf8_lossy(&bytes[..end]).to_ascii_lowercase();let length=headers.lines().find_map(|l|l.strip_prefix("content-length:").and_then(|s|s.trim().parse::<usize>().ok())).unwrap_or(0);if bytes.len()>=end+4+length{break}}}socket.write_all(format!("HTTP/1.1 {status} Result\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).as_bytes()).await.unwrap();String::from_utf8(bytes).unwrap()});(format!("http://{address}"),task)}
#[tokio::test]async fn sdk_auth_uses_owner_headers_and_never_bearer(){let(origin,task)=server(200,r#"{"skills":[],"total":0}"#).await;let client=Client::new(&origin).unwrap().authenticated_api_key("synthetic-key".into(),"tenant".into(),Some("owner".into())).unwrap();client.instruction_skills(true).await.unwrap();let request=task.await.unwrap().to_ascii_lowercase();assert!(request.contains("x-api-key:"));assert!(request.contains("x-tenant-id: tenant"));assert!(request.contains("x-user-id: owner"));assert!(request.contains("x-request-id:"));assert!(!request.contains("authorization:"));}
#[tokio::test]async fn image_admission_503_is_unknown_without_retry(){let(origin,task)=server(503,"{}").await;let client=Client::new(&origin).unwrap().authenticated("synthetic-session".into());let result=client.assistant_image(json!({"prompt":"sunset","model_id":"model","n":1}),true).await;assert!(matches!(result,Err(Error::UnknownOutcome)));let request=task.await.unwrap();assert!(request.starts_with("POST /api/v1/assistant/generate-image-async "));}
#[tokio::test]async fn image_admission_invalid_task_receipt_is_unknown(){let(origin,task)=server(200,r#"{"task_id":"bad/id","status":"queued"}"#).await;let client=Client::new(&origin).unwrap().authenticated("synthetic-session".into());assert!(matches!(client.assistant_image(json!({"prompt":"p","model_id":"m"}),true).await,Err(Error::UnknownOutcome)));task.await.unwrap();}
